class SmaAnalysis {
public:
    void set_params(const nlohmann::json& params) {
        period_ = params.value("period", 20);
        if (period_ < 1) period_ = 1;
        sum_ = 0.0;
        window_.clear();
        window_.reserve(static_cast<std::size_t>(period_));
    }
    void update(BarContext& ctx) {
        sum_ += ctx.bar.close;
        window_.push_back(ctx.bar.close);
        if (static_cast<int>(window_.size()) > period_) {
            sum_ -= window_.front();
            window_.erase(window_.begin());
        }
        ctx.sma = window_.empty() ? 0.0 : sum_ / static_cast<double>(window_.size());
        ctx.sma_ready = static_cast<int>(window_.size()) >= period_;
    }
private:
    int period_ = 20;
    double sum_ = 0.0;
    std::vector<double> window_;
};

class SmaCrossEntry {
public:
    void set_params(const nlohmann::json& params) {
        (void)params;
    }
    bool evaluate(const BarContext& ctx) {
        return ctx.sma_ready && ctx.bar.close > ctx.sma;
    }
    int direction(const BarContext& ctx) {
        (void)ctx;
        return 1;
    }
    double confidence(const BarContext& ctx) {
        (void)ctx;
        return 1.0;
    }
    std::string reason() const {
        return "sma_cross_long";
    }
};

class NBarExit {
public:
    void set_params(const nlohmann::json& params) {
        hold_bars_ = params.value("hold_bars", 5);
        if (hold_bars_ < 1) hold_bars_ = 1;
        bars_since_entry_ = -1;
    }
    bool evaluate(const BarContext& ctx) {
        (void)ctx;
        if (bars_since_entry_ < 0) {
            bars_since_entry_ = 0;
            return false;
        }
        ++bars_since_entry_;
        if (bars_since_entry_ >= hold_bars_) {
            bars_since_entry_ = -1;
            return true;
        }
        return false;
    }
    std::string reason() const {
        return "n_bar_exit";
    }
private:
    int hold_bars_ = 5;
    int bars_since_entry_ = -1;
};
